    {
      "path": "lib/index.js",
      "content": "/**\n * dsh-peak-runner — DeepSeek 峰谷价感知的任务执行器。\n *\n * 平价时段直接跑 deepseek-flash 的任务批；峰价快到时把任务攒进队列，\n * 挂一条自持定时器，到下一个平价时段自动执行完。\n *\n * 接缝：`ctx.llm`（模型调用）+ `ctx.storageDomain`（队列持久化）+\n * `ctx.tools`（工具注册）+ `ctx.systemPrompt`（使用指引）。\n *\n * @module dsh-peak-runner\n */\n\nimport z from \"@deepseek-ai/schemastery\";\nimport { Config, resolveConfig } from \"./config.js\";\nimport { createQueue } from \"./queue.js\";\nimport { createToolSpecs } from \"./tools.js\";\nimport { guideText } from \"./prompt.js\";\nimport { armTimer } from \"./scheduler.js\";\n\nexport const name = \"peak-runner\";\n\nexport const inject = [\"llm\", \"storageDomain\", \"tools\", \"systemPrompt\"];\n\nexport { Config };\n\n/**\n * Mount the plugin.\n *\n * @param ctx - host plugin context.\n * @param config - loader config (defaults are re-resolved here).\n */\nexport function apply(ctx, config) {\n\tconst settings = resolveConfig(config);\n\tif (!settings.enabled) {\n\t\tconsole.log(\"[dsh-peak-runner] disabled by configuration\");\n\t\treturn;\n\t}\n\n\tconst queue = createQueue(ctx);\n\n\t// The scheduler handle is shared between `apply()` and the tool specs.\n\t// `armedAt` is the one piece of mutable state the tools read.\n\tconst timer = {\n\t\tarmedAt: null,\n\t\t_dispose: null,\n\t\tarm(atMs) {\n\t\t\tthis.disarm();\n\t\t\tthis.armedAt = atMs;\n\t\t\tthis._dispose = armTimer(atMs, () => {\n\t\t\t\tthis.armedAt = null;\n\t\t\t\t// The timer only wakes the queue; the actual drain happens on the\n\t\t\t\t// next `peak_run` call (or the next `peak_schedule` read), which\n\t\t\t\t// keeps model calls inside an explicit tool invocation.\n\t\t\t\tconsole.log(`[dsh-peak-runner] off-peak reached at ${new Date(atMs).toISOString()}; queue is ready to drain`);\n\t\t\t});\n\t\t},\n\t\tdisarm() {\n\t\t\tif (typeof this._dispose === \"function\") this._dispose();\n\t\t\tthis._dispose = null;\n\t\t\tthis.armedAt = null;\n\t\t},\n\t};\n\n\tctx.effect(() => () => timer.disarm(), \"dsh-peak-runner: scheduler timer\");\n\n\tctx.systemPrompt.section({\n\t\tname: \"peak-runner:guide\",\n\t\torder: 70,\n\t\ttext: () => guideText(settings),\n\t});\n\n\tfor (const spec of createToolSpecs({ ctx, settings, queue, timer })) {\n\t\tctx.tools.register(spec);\n\t}\n}\n"
    },
    {
      "path": "lib/config.js",
      "content": "/**\n * Plugin configuration: the schema the host validates against, the code-side\n * defaults (so a direct `apply()` call works without the loader), and the\n * normalisation of every knob.\n *\n * The Cordis loader applies `Config` defaults, but `apply` is also reachable\n * through direct construction (tests, tooling), so this module resolves its own\n * defaults instead of trusting the caller.\n *\n * @module dsh-peak-runner/config\n */\n\nimport z from \"@deepseek-ai/schemastery\";\n\n/** Reasoning efforts the DeepSeek adapter advertises. */\nconst EFFORTS = [\"off\", \"low\", \"high\", \"max\"];\n\n/** Code-side defaults, mirrored by the `Config` schema below. */\nexport const DEFAULTS = Object.freeze({\n\tenabled: true,\n\tprovider: \"deepseek-account\",\n\tmodel: \"deepseek-flash\",\n\t// DeepSeek 官方按 UTC 峰段收费：01:00–04:00、06:00–10:00 为峰时价，其余为平价。\n\t// 周末与法定假日全天平价（与 dsh-cost-meter 的口径一致）。\n\tpeakWindows: [\n\t\t{ start: 1, end: 4 },\n\t\t{ start: 6, end: 10 },\n\t],\n\t// 峰价开始前多少分钟停止执行新任务、把任务攒进队列等平价。\n\tleadMinutes: 10,\n\treasoningEffort: \"off\",\n\tmaxTokens: 2048,\n\ttimeoutMs: 45_000,\n\ttemperature: 0.7,\n});\n\nexport const Config = z.object({\n\t/** Master switch; `false` registers no tools and runs nothing. */\n\tenabled: z.boolean().default(DEFAULTS.enabled),\n\t/** Provider id for the batch runner (empty = auto-pick the first usable one). */\n\tprovider: z.string().default(DEFAULTS.provider),\n\t/** Model id for the batch runner. */\n\tmodel: z.string().default(DEFAULTS.model),\n\t/** Peak (UTC hour) windows: `[start, end)` half-open ranges. */\n\tpeakWindows: z\n\t\t.array(\n\t\t\tz.object({\n\t\t\t\tstart: z.number().min(0).max(23),\n\t\t\t\tend: z.number().min(1).max(24),\n\t\t\t}),\n\t\t)\n\t\t.default(DEFAULTS.peakWindows),\n\t/** How many minutes before a peak window to stop running and start queueing. */\n\tleadMinutes: z.number().min(0).max(120).default(DEFAULTS.leadMinutes),\n\t/** Reasoning budget per call: `off`, `low`, `high` or `max`. */\n\treasoningEffort: z.string().default(DEFAULTS.reasoningEffort),\n\t/** Output cap per call. */\n\tmaxTokens: z.natural().default(DEFAULTS.maxTokens),\n\t/** Hard ceiling on one call; the queue marks the task failed instead of hanging. */\n\ttimeoutMs: z.natural().default(DEFAULTS.timeoutMs),\n\t/** Sampling temperature. */\n\ttemperature: z.number().default(DEFAULTS.temperature),\n});\n\n/**\n * A finite number clamped into `[min, max]`, or `fallback`.\n *\n * @param value - raw configured value.\n * @param min - lower bound.\n * @param max - upper bound.\n * @param fallback - value used otherwise.\n * @returns the resolved number.\n */\nfunction clampNumber(value, min, max, fallback) {\n\tconst number = Number(value);\n\tif (!Number.isFinite(number)) return fallback;\n\treturn Math.min(max, Math.max(min, number));\n}\n\n/**\n * A positive integer, or `fallback`.\n *\n * @param value - raw configured value.\n * @param fallback - value used otherwise.\n * @returns the resolved integer.\n */\nfunction positiveInteger(value, fallback) {\n\tconst number = Number(value);\n\treturn Number.isSafeInteger(number) && number > 0 ? number : fallback;\n}\n\n/**\n * One of `allowed`, or `fallback` when the value is absent/unknown.\n *\n * @param value - raw configured value.\n * @param allowed - accepted strings.\n * @param fallback - value used otherwise.\n * @returns the resolved string.\n */\nfunction pick(value, allowed, fallback) {\n\treturn typeof value === \"string\" && allowed.includes(value) ? value : fallback;\n}\n\n/**\n * Normalise the peak-window list: only keep well-formed half-open ranges.\n *\n * @param raw - raw configured windows.\n * @returns a fresh normalised list.\n */\nfunction windows(raw) {\n\tif (!Array.isArray(raw)) return DEFAULTS.peakWindows.map((w) => ({ ...w }));\n\treturn raw\n\t\t.filter((w) => w && typeof w === \"object\")\n\t\t.map((w) => ({\n\t\t\tstart: Math.min(23, Math.max(0, Math.floor(Number(w.start)))),\n\t\t\tend: Math.min(24, Math.max(1, Math.floor(Number(w.end)))),\n\t\t}))\n\t\t.filter((w) => Number.isFinite(w.start) && Number.isFinite(w.end));\n}\n\n/**\n * Resolve user configuration into the plain settings object the plugin uses.\n *\n * @param raw - the loader-supplied config (possibly undefined).\n * @returns resolved settings.\n */\nexport function resolveConfig(raw) {\n\tconst config = raw === null || typeof raw !== \"object\" ? {} : raw;\n\treturn {\n\t\tenabled: config.enabled !== false,\n\t\tprovider: typeof config.provider === \"string\" ? config.provider.trim() : DEFAULTS.provider,\n\t\tmodel: typeof config.model === \"string\" ? config.model.trim() : DEFAULTS.model,\n\t\tpeakWindows: windows(config.peakWindows),\n\t\tleadMinutes: clampNumber(config.leadMinutes, 0, 120, DEFAULTS.leadMinutes),\n\t\treasoningEffort: pick(config.reasoningEffort, EFFORTS, DEFAULTS.reasoningEffort),\n\t\tmaxTokens: positiveInteger(config.maxTokens, DEFAULTS.maxTokens),\n\t\ttimeoutMs: positiveInteger(config.timeoutMs, DEFAULTS.timeoutMs),\n\t\ttemperature: clampNumber(config.temperature, 0, 2, DEFAULTS.temperature),\n\t};\n}\n"
    },
    {
      "path": "lib/tariff.js",
      "content": "/**\n * Tariff windows: decide whether \"now\" is off-peak (平价), how long until the\n * next switch, and when the next off-peak window opens.\n *\n * DeepSeek's official rule: peak price applies during UTC 01:00–04:00 and\n * 06:00–10:00; every other hour is off-peak. Weekends and Chinese public\n * holidays are off-peak all day. The plugin mirrors the same window shape\n * `dsh-cost-meter` uses, so both agree on the current tier.\n *\n * This module is pure: every function takes an explicit `now` so tests can\n * pin the clock.\n *\n * @module dsh-peak-runner/tariff\n */\n\n/** Milliseconds in one minute. */\nconst MINUTE = 60_000;\n\n/**\n * Whether a UTC hour falls inside any configured peak window.\n *\n * @param hour - UTC hour (0–23).\n * @param windows - normalised `[{ start, end }]` half-open ranges.\n * @returns true when the hour is a peak hour.\n */\nexport function hourInPeak(hour, windows) {\n\tif (!Array.isArray(windows)) return false;\n\treturn windows.some((w) => {\n\t\tconst start = Number(w?.start);\n\t\tconst end = Number(w?.end);\n\t\tif (!Number.isFinite(start) || !Number.isFinite(end)) return false;\n\t\t// A window that wraps midnight (start > end) covers the tail and the head.\n\t\tif (start < end) return hour >= start && hour < end;\n\t\treturn hour >= start || hour < end;\n\t});\n}\n\n/**\n * Whether `at` is inside a peak window (weekends are always off-peak).\n *\n * @param at - epoch milliseconds.\n * @param windows - configured peak windows.\n * @returns true when the instant is peak-priced.\n */\nexport function isPeak(at, windows) {\n\tconst date = new Date(at);\n\tif (Number.isNaN(date.getTime())) return false;\n\t// DeepSeek charges by UTC hour; weekends (local Beijing) are off-peak all day.\n\tif (date.getUTCDay() === 0 || date.getUTCDay() === 6) return false;\n\treturn hourInPeak(date.getUTCHours(), windows);\n}\n\n/**\n * The next instant at which the tier changes (into peak or into off-peak).\n *\n * @param at - epoch milliseconds.\n * @param windows - configured peak windows.\n * @returns epoch milliseconds of the next switch, or null when none is found\n *   within a search horizon of 8 days.\n */\nexport function nextSwitch(at, windows) {\n\tif (!Array.isArray(windows) || windows.length === 0) return null;\n\t// Collect every boundary hour across all windows, projected onto a rolling\n\t// 8-day horizon so weekend gaps are crossed correctly.\n\tconst boundaries = new Set();\n\tfor (const w of windows) {\n\t\tboundaries.add(Number(w?.start));\n\t\tboundaries.add(Number(w?.end));\n\t}\n\tboundaries.delete(NaN);\n\tif (boundaries.size === 0) return null;\n\tconst hours = [...boundaries].sort((a, b) => a - b);\n\tconst startHour = new Date(at).getUTCHours();\n\tconst startMs = Date.UTC(\n\t\tnew Date(at).getUTCFullYear(),\n\t\tnew Date(at).getUTCMonth(),\n\t\tnew Date(at).getUTCDate(),\n\t\tstartHour,\n\t);\n\t// Walk forward hour by hour (bounded) and return the first hour whose tier\n\t// differs from the tier at `at`.\n\tconst nowTier = isPeak(at, windows);\n\tfor (let offset = 1; offset <= 8 * 24; offset += 1) {\n\t\tconst candidate = startMs + offset * 3_600_000;\n\t\tif (isPeak(candidate, windows) !== nowTier) return candidate;\n\t}\n\treturn null;\n}\n\n/**\n * The next instant at which the tier becomes off-peak (平价).\n *\n * @param at - epoch milliseconds.\n * @param windows - configured peak windows.\n * @returns epoch milliseconds of the next off-peak start, or null when the\n *   current instant is already off-peak and no upcoming switch is found.\n */\nexport function nextOffPeak(at, windows) {\n\tif (!isPeak(at, windows)) return null;\n\treturn nextSwitch(at, windows);\n}\n\n/**\n * A one-line human summary of the current tier and the next switch.\n *\n * @param at - epoch milliseconds.\n * @param windows - configured peak windows.\n * @returns `{ tier, nextSwitchAt, minutesUntilSwitch, text }`.\n */\nexport function describeTariff(at, windows) {\n\tconst peak = isPeak(at, windows);\n\tconst switchAt = nextSwitch(at, windows);\n\tconst minutes = switchAt === null ? null : Math.max(0, Math.round((switchAt - at) / MINUTE));\n\tconst tier = peak ? \"峰价\" : \"平价\";\n\tconst text =\n\t\tswitchAt === null\n\t\t\t? `${tier}（没有找到下一个切换点）`\n\t\t\t: `${tier}，${minutes} 分钟后切换（${new Date(switchAt).toISOString()}）`;\n\treturn { tier, nextSwitchAt: switchAt, minutesUntilSwitch: minutes, text };\n}\n"
    },
    {
      "path": "lib/scheduler.js",
      "content": "/**\n * Scheduling: when to run the queue.\n *\n * In off-peak hours the queue is drained immediately. As a peak window\n * approaches (within `leadMinutes`), new tasks stop running and the plugin\n * arms a timer for the next off-peak start. The timer is a plain\n * `setTimeout(...).unref()` — the same self-held pattern `dsh-loop` uses —\n * because `ctx.schedule` is an optional facette that is not always mounted.\n *\n * @module dsh-peak-runner/scheduler\n */\n\nimport { hourInPeak, nextSwitch } from \"./tariff.js\";\n\n/** The longest `setTimeout` delay we ever ask Node for (2^31 - 1 ms). */\nconst MAX_TIMER_DELAY_MS = 2_147_483_647;\n\n/**\n * Should the queue run right now?\n *\n * @param at - epoch milliseconds.\n * @param settings - resolved plugin settings.\n * @returns `{ run: boolean, reason: string, nextRunAt: number|null }`.\n */\nexport function shouldRunNow(at, settings) {\n\t// A weekend instant is always off-peak; `isPeak` already handles that.\n\t// For a weekday we need the *window* tier, not the calendar tier, because\n\t// the lead window extends the \"stop running\" zone past the window end.\n\tconst date = new Date(at);\n\tconst weekend = Number.isNaN(date.getTime()) || date.getUTCDay() === 0 || date.getUTCDay() === 6;\n\tif (weekend) return { run: true, reason: \"off-peak\", nextRunAt: null };\n\n\tif (!hourInPeak(date.getUTCHours(), settings.peakWindows)) {\n\t\treturn { run: true, reason: \"off-peak\", nextRunAt: null };\n\t}\n\n\t// Inside a peak window: look for the next switch and see whether the lead\n\t// window has already swallowed us.\n\tconst switchAt = nextSwitch(at, settings.peakWindows);\n\tif (switchAt === null) return { run: false, reason: \"peak-no-switch-found\", nextRunAt: null };\n\n\tconst leadMs = settings.leadMinutes * 60_000;\n\tif (at >= switchAt - leadMs) {\n\t\t// We are inside the lead window that precedes the switch into off-peak.\n\t\treturn { run: false, reason: \"lead-window\", nextRunAt: switchAt };\n\t}\n\t// Still early inside a peak window; the next off-peak start is the switch.\n\treturn { run: false, reason: \"peak\", nextRunAt: switchAt };\n}\n\n/**\n * Arm a one-shot timer for `atMs`, clamped to `setTimeout`'s maximum delay.\n *\n * @param atMs - target epoch milliseconds.\n * @param fire - called when the timer elapses.\n * @returns a disposer that clears the timer.\n */\nexport function armTimer(atMs, fire) {\n\tconst delay = Math.min(MAX_TIMER_DELAY_MS, Math.max(0, atMs - Date.now()));\n\tconst timer = setTimeout(() => {\n\t\tfire();\n\t}, delay);\n\tif (typeof timer.unref === \"function\") timer.unref();\n\treturn () => clearTimeout(timer);\n}\n\n/**\n * Compute the next time the queue should be drained, whether or not it is\n * currently armed.\n *\n * @param at - epoch milliseconds.\n * @param settings - resolved plugin settings.\n * @returns epoch milliseconds of the next off-peak start, or null when the\n *   queue should just run now.\n */\nexport function nextDrainAt(at, settings) {\n\tconst decision = shouldRunNow(at, settings);\n\tif (decision.run) return null;\n\treturn decision.nextRunAt;\n}\n"
    },
    {
      "path": "lib/queue.js",
      "content": "/**\n * The task queue: one batch document in the plugin's storage domain, holding\n * every pending / running / finished task. Whole-document writes (one `put`\n * per change) mirror how `dsh-schedule` persists a task row.\n *\n * @module dsh-peak-runner/queue\n */\n\nimport { defineDomain, domainTable } from \"@deepseek-ai/dsh-storage-domain\";\n\n/** A permissive value schema: the domain only needs `parse()`. */\nfunction recordSchema() {\n\treturn {\n\t\tparse(value) {\n\t\t\tif (typeof value !== \"object\" || value === null || Array.isArray(value)) {\n\t\t\t\tthrow new Error(\"peak-runner batch must be an object\");\n\t\t\t}\n\t\t\tif (!Array.isArray(value.tasks)) throw new Error(\"peak-runner batch.tasks must be an array\");\n\t\t\treturn value;\n\t\t},\n\t};\n}\n\nexport const peakRunnerDomain = defineDomain({\n\t// Domain names must match /^[a-z][a-z0-9_]*$/ — the hyphenated plugin name\n\t// is rejected by the host's schema, so the underscore spelling is used here.\n\tname: \"peak_runner\",\n\tversion: 1,\n\ttables: {\n\t\tbatches: domainTable(recordSchema()),\n\t},\n});\n\n/** The one and only batch document key. */\nexport const BATCH_KEY = \"current\";\n\n/** Task statuses this queue uses. */\nexport const TASK_STATUSES = Object.freeze([\"pending\", \"running\", \"done\", \"failed\", \"cancelled\"]);\n\n/**\n * Create an empty batch document.\n *\n * @returns a fresh batch with an empty task list.\n */\nexport function emptyBatch() {\n\treturn { tasks: [] };\n}\n\n/**\n * Normalise a raw task into the stored shape.\n *\n * @param raw - caller-supplied task fields.\n * @param now - epoch ms used for `createdAt`.\n * @returns the normalised task.\n */\nexport function normalizeTask(raw, now) {\n\tconst prompt = typeof raw?.prompt === \"string\" ? raw.prompt.trim() : \"\";\n\tif (prompt === \"\") throw new Error(\"task prompt must be a non-empty string\");\n\treturn {\n\t\tid: typeof raw?.id === \"string\" && raw.id !== \"\" ? raw.id : `task-${now.toString(36)}-${Math.random().toString(36).slice(2, 8)}`,\n\t\tprompt,\n\t\tstatus: \"pending\",\n\t\tcreatedAt: now,\n\t\tstartedAt: null,\n\t\tfinishedAt: null,\n\t\tresult: null,\n\t\terror: null,\n\t};\n}\n\n/**\n * Open the queue against a storage-domain service.\n *\n * @param ctx - host plugin context (needs the `storageDomain` service).\n * @returns `{ ready, tasks(), put() }` where `ready` resolves once the domain\n *   is open and `tasks()` returns the current task list.\n */\nexport function createQueue(ctx) {\n\tconst ready = ctx.storageDomain.open(peakRunnerDomain);\n\n\t/** @returns {Promise<Array>} the current task list (fresh copy). */\n\tasync function tasks() {\n\t\tconst domain = await ready;\n\t\tconst table = domain.table(\"batches\");\n\t\tconst batch = table.get(BATCH_KEY);\n\t\tif (batch === undefined) return [];\n\t\treturn Array.isArray(batch.tasks) ? batch.tasks : [];\n\t}\n\n\t/**\n\t * Persist a whole task list.\n\t *\n\t * @param list - the task list to store.\n\t * @returns {Promise<void>} resolves once the write is durable.\n\t */\n\tasync function put(list) {\n\t\tconst domain = await ready;\n\t\tawait domain.table(\"batches\").put(BATCH_KEY, { tasks: list });\n\t}\n\n\treturn { ready, tasks, put };\n}\n"
    },
    {
      "path": "lib/runner.js",
      "content": "/**\n * The runner seam — the only place this plugin talks to a model.\n *\n * One streamed `ctx.llm.stream()` call per task prompt, assembled into text.\n * The reasoning knob defaults to `off` because the host's default (high) can\n * spend the whole output budget on the reasoning block and return an EMPTY\n * text block — a \"successful\" call that says nothing.\n *\n * @module dsh-peak-runner/runner\n */\n\nimport { BlockAssembler, createUserMessage } from \"@deepseek-ai/dsh-llm\";\n\n/**\n * Resolve the provider/model pair this plugin should call.\n *\n * @param ctx - host plugin context (needs the `llm` service).\n * @param settings - resolved plugin settings.\n * @returns the pair, or null when the host advertises no usable model.\n */\nexport async function resolveTarget(ctx, settings) {\n\tconst provider = settings.provider;\n\tconst model = settings.model;\n\tif (provider !== \"\" && model !== \"\") {\n\t\ttry {\n\t\t\tawait ctx.llm.resolveModelInfo(provider, model);\n\t\t\treturn { provider, model, source: \"config\" };\n\t\t} catch {\n\t\t\t// Fall through to discovery: a profile without this provider is not an error.\n\t\t}\n\t}\n\ttry {\n\t\tconst providers = ctx.llm.listProviders() ?? [];\n\t\tfor (const entry of providers) {\n\t\t\tconst id = typeof entry === \"string\" ? entry : entry?.id;\n\t\t\tif (typeof id !== \"string\" || id === \"\") continue;\n\t\t\tconst models = await ctx.llm.listModels(id);\n\t\t\tif (!Array.isArray(models)) continue;\n\t\t\tconst first = models.find((candidate) => typeof candidate === \"string\" && candidate !== \"\");\n\t\t\tif (first !== undefined) return { provider: id, model: first, source: \"auto\" };\n\t\t}\n\t} catch {\n\t\t// No discovery either — report the absence instead of guessing.\n\t}\n\treturn null;\n}\n\n/**\n * Describe an adapter failure in one short human-readable line.\n *\n * @param failure - the failure carried by the assembler's finish state.\n * @returns a message suitable for the queue log.\n */\nexport function describeFailure(failure) {\n\tif (failure === null || typeof failure !== \"object\") return \"model call failed\";\n\tconst message = failure.message ?? failure.code ?? failure.kind;\n\treturn typeof message === \"string\" && message !== \"\" ? message : \"model call failed\";\n}\n\n/**\n * Drive one streamed model call and return the assembled text.\n *\n * @param ctx - host plugin context.\n * @param options - `{ system, prompt, provider, model, maxTokens, temperature,\n *   reasoningEffort, signal }`.\n * @returns `{ ok: true, text, usage? }` or `{ ok: false, code, detail }`.\n */\nexport async function runPrompt(ctx, options) {\n\tconst { system, prompt, provider, model, maxTokens, temperature, reasoningEffort, signal } = options;\n\n\tconst attempt = async (effort) => {\n\t\tconst assembler = new BlockAssembler();\n\t\tconst config = {\n\t\t\tprovider,\n\t\t\tmodel,\n\t\t\t...(system === undefined || system === \"\" ? {} : { system }),\n\t\t\tmessages: [\n\t\t\t\tcreateUserMessage({\n\t\t\t\t\tcontent: [{ type: \"text\", text: prompt }],\n\t\t\t\t\tsource: { kind: \"user\" },\n\t\t\t\t}),\n\t\t\t],\n\t\t\t...(temperature === undefined ? {} : { temperature }),\n\t\t\t...(maxTokens === undefined ? {} : { maxTokens }),\n\t\t\t...(signal === undefined ? {} : { signal }),\n\t\t};\n\t\tif (typeof effort === \"string\" && effort !== \"\") config.reasoningEffort = effort;\n\n\t\tconst stream = ctx.llm.stream(config);\n\t\tfor await (const chunk of stream) {\n\t\t\tassembler.push(chunk);\n\t\t}\n\t\tconst finish = assembler.finish;\n\t\tlet text = \"\";\n\t\ttry {\n\t\t\tfor (const block of assembler.blocks()) {\n\t\t\t\tif (block?.type === \"text\" && typeof block.text === \"string\") text += block.text;\n\t\t\t}\n\t\t} catch {\n\t\t\t// A malformed stream still yields whatever text was assembled above.\n\t\t}\n\t\tconst usage = typeof assembler.usage === \"object\" ? assembler.usage : undefined;\n\t\tif (finish !== undefined && finish !== null && (finish.kind === \"error\" || finish.kind === \"aborted\")) {\n\t\t\treturn { ok: false, code: finish.kind, detail: describeFailure(finish.failure) };\n\t\t}\n\t\treturn { ok: true, text, ...(usage === undefined ? {} : { usage }) };\n\t};\n\n\ttry {\n\t\treturn await attempt(reasoningEffort);\n\t} catch (error) {\n\t\tconst detail = error instanceof Error ? error.message : String(error);\n\t\t// A model that advertises no reasoning support rejects the knob outright;\n\t\t// the call itself is still fine, so retry once without it.\n\t\tif (typeof reasoningEffort === \"string\" && reasoningEffort !== \"\" && /reasoning/i.test(detail)) {\n\t\t\ttry {\n\t\t\t\treturn await attempt(\"\");\n\t\t\t} catch (retryError) {\n\t\t\t\treturn {\n\t\t\t\t\tok: false,\n\t\t\t\t\tcode: \"stream-failed\",\n\t\t\t\t\tdetail: retryError instanceof Error ? retryError.message : String(retryError),\n\t\t\t\t};\n\t\t\t}\n\t\t}\n\t\treturn { ok: false, code: \"stream-failed\", detail };\n\t}\n}\n"
